# config.sh: key=value config access
CFG_FILE=${CFG_FILE:-etc/app.conf}

# config_get KEY: print the value of KEY (exit 1 + message if missing)
config_get() {
  local line
  line=$(grep -m1 "^$1=" "$CFG_FILE") || { echo "get_cfg: missing key $1" >&2; return 1; }
  echo "${line#*=}"
}

# get_cfg_path KEY: like config_get, but resolves a relative value against the
# directory of the config file
get_cfg_path() {
  local v
  v=$(config_get "$1") || return 1
  case $v in
    /*) echo "$v" ;;
    *) echo "$(dirname "$CFG_FILE")/$v" ;;
  esac
}

# get_cfg_or KEY DEFAULT
get_cfg_or() { config_get "$1" 2>/dev/null || echo "$2"; }

# forget_cfg: drop the configured file name
forget_cfg() { unset CFG_FILE; }
